// The area of a unit circle within a rectangle defined by two 2d cartesian coordinates
// The technique here is to integrate the 1d semi-circle function 'sqrt(1 - x^2)' for top and bottom halves
// Maths: https://www.desmos.com/calculator/va08mxx3qh

const float PI = 3.1415926535;

// integrate a unit half circle in 1D at a position with a y_offset
float integrate_1d(in float pos, in float offset) {
    return ((asin(pos) + pos * sqrt(1.0 - pow(pos, 2.0))) / 2.0) - (offset * pos);
}

// returns the position on the circle based on a x/y provided (opposite axis)
float circle_intersect(in float pos) {
    return sqrt(1.0 - pow(pos, 2.0));
}

// integrate a unit half circle in 1D with given bounds
float integrate_bounded(in float from, in float to, in float offset) {
    return integrate_1d(to, offset) - integrate_1d(from, offset);
}

// integrates the semi circle trimming any x outside the circle (determined by the intersection)
float integrate_semi(in float from, in float to, in float offset) {
    float limit = circle_intersect(offset);
    return integrate_bounded(clamp(from, -limit, limit), clamp(to, -limit, limit), offset);
}

// calculate the area of a unit circle from two cartesian coords, axis between 0..1
float integrate_unit_circle(in vec2 from, in vec2 to) {
	// normalise to -1..1 range
    vec2 from_pos = clamp(min(from, to), 0.0, 1.0) * 2.0 - 1.0;
	vec2 to_pos = clamp(max(from, to), 0.0, 1.0) * 2.0 - 1.0;

    // limited y coords for the top and bottom halves of the circle
    vec2 top = clamp(vec2(from_pos.y, to_pos.y), 0.0, 1.0);
    vec2 bottom = clamp(vec2(to_pos.y, from_pos.y), -1.0, 0.0);

    // integrate the top
    float area = integrate_semi(from_pos.x, to_pos.x, top.x) - integrate_semi(from_pos.x, to_pos.x, top.y);

    // flip the coords for the bottom
    area += integrate_semi(from_pos.x, to_pos.x, -bottom.x) - integrate_semi(from_pos.x, to_pos.x, -bottom.y);

    // need to divide by 4 because the unit circle covers -1..1 in both axis which has an area of 4
    return area / 4.0;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float scale = 1.0 / iResolution.y;

    // assume wide aspect so cover y and then center
    vec2 uv = (fragCoord - vec2(iResolution.x - iResolution.y, 0.0) / 2.0) * scale;

    // draw a circle with blur by integrating with bounds over a pixel range
    float blur_amount = floor(((sin(PI * (iTime * 0.5 - 0.5))+1.0) / 2.0) * iResolution.y);
    float pixel_size = (blur_amount + 1.0) * scale;
    float pixel_area = pixel_size * pixel_size;

    float area = integrate_unit_circle(uv - pixel_size/2.0, uv + pixel_size/2.0) / pixel_area;

    fragColor = vec4(vec3(area), 1.0);
}
